import{_ as l,a0 as o,w as d,s as r,ao as p,I as n,x as t,a1 as i,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"三件可以用 systemd 做的令人惊讶的事情 | LCTT x X-CMD","titleTemplate":false,"description":"三件可以用 systemd 做的令人惊讶的事情 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"三件可以用 systemd 做的令人惊讶的事情 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"三件可以用 systemd 做的令人惊讶的事情 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20230323.2 ⭐️ 3 surprising things Linux sysadmins can do with systemd","title":"三件可以用 systemd 做的令人惊讶的事情","tag":"202304","desc":""},"relativePath":"202304/20230323.2 ⭐️ 3 surprising things Linux sysadmins can do with systemd.md","filePath":"[post].md"}'),u={name:"202304/20230323.2 ⭐️ 3 surprising things Linux sysadmins can do with systemd.md"};function m(g,s,y,f,k,b){const e=o("Link");return d(),r("div",null,[s[41]||(s[41]=p('<h1 id="三件可以用-systemd-做的令人惊讶的事情" tabindex="-1">三件可以用 systemd 做的令人惊讶的事情 <a class="header-anchor" href="#三件可以用-systemd-做的令人惊讶的事情" aria-label="Permalink to “三件可以用 systemd 做的令人惊讶的事情”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202304/02/135545u0rwtqdemqefme3e.jpg" alt=""></p><blockquote><p>它不仅仅是为了让你的电脑启动得更快。</p></blockquote><p>当 systemd 刚问世时，有很多关于它能加快启动时间的消息。这项功能对大多数人都有吸引力（对那些不重启的人来说就不那么重要了），所以在很多方面，这也是它今天仍然拥有的声誉。虽然 systemd 确实是在启动过程中并行启动服务起到了作用，但它的作用远不止于此。以下是你可能没有意识到 systemd 可以做的三件事，但你应该好好利用。</p><h3 id="_1、简化-linux-ps" tabindex="-1">1、简化 Linux ps <a class="header-anchor" href="#_1、简化-linux-ps" aria-label="Permalink to “1、简化 Linux ps”">​</a></h3><p>如果你曾经使用过 <code>ps</code>，甚至只是 <code>top</code> 命令，那么你就会知道你的电脑一直都在运行数百个进程。有时，这正是你需要的信息，以便了解你的计算机或其用户在做什么。其他时候，你真正需要的是一个总体的概览。</p>',6)),n("p",null,[s[1]||(s[1]=n("code",null,"systemd-cgtop",-1)),s[2]||(s[2]=t(" 命令提供了一个基于",-1)),s[3]||(s[3]=n("ruby",null,[t("控制组"),n("rt",null,"cgroup")],-1)),s[4]||(s[4]=t("任务安排的计算机负载的简单视图。",-1)),i(e,{href:"https://www.redhat.com/sysadmin/cgroups-part-four?intcmp=7013a000002qLH8AAM"},{default:a(()=>[...s[0]||(s[0]=[t("控制组",-1)])]),_:1}),s[5]||(s[5]=t(" 对现代 Linux 很重要，基本上是容器和 Kubernetes 的底层支持结构（这也是云计算可以扩展的原因），但它们也是家庭电脑上的有用结构。例如，从 ",-1)),s[6]||(s[6]=n("code",null,"systemd-cgtop",-1)),s[7]||(s[7]=t(" 的输出中，你可以看到用户进程的负载，而不是系统进程：",-1))]),s[42]||(s[42]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Control Group               Proc+   %CPU   Memory  Input/s Output/s</span></span>
<span class="line"><span>/                             183    5.0     1.6G       0B     3.0M</span></span>
<span class="line"><span>user.slice                      4    2.8     1.1G       0B   174.7K</span></span>
<span class="line"><span>user.slice/user-1000.slice      4    2.8   968.2M       0B   174.7K</span></span>
<span class="line"><span>system.slice                   65    2.2     1.5G       0B     2.8M</span></span></code></pre></div><p>你也可以只查看你的用户空间进程，或者查看用户空间进程和内核线程。</p><p>这绝不是对 <code>top</code> 或 <code>ps</code> 的替代，而是从一个不同的、独特的角度来观察你的系统。在运行容器时，它可能是至关重要的，因为容器使用控制组。</p><h3 id="_2、linux-定时任务" tabindex="-1">2、Linux 定时任务 <a class="header-anchor" href="#_2、linux-定时任务" aria-label="Permalink to “2、Linux 定时任务”">​</a></h3>`,4)),n("p",null,[i(e,{href:"https://opensource.com/article/17/11/how-use-cron-linux"},{default:a(()=>[...s[8]||(s[8]=[t("Cron",-1)])]),_:1}),s[9]||(s[9]=t(" 是 Linux 的一个经典组件。当你想安排一些事情定期发生时，你会使用 Cron。它很可靠，而且相当好地集成到你的系统中。",-1))]),s[43]||(s[43]=n("p",null,"问题是，Cron 并不了解有些计算机会被关闭。如果你有一个安排在午夜的 Cron 任务，但你每天在 23:59 关闭你的电脑，那么你的 Cron 任务就永远不会运行。Cron 没有任何工具可以检测到一夜之间错过了工作。",-1)),n("p",null,[s[11]||(s[11]=t("作为对这个问题的回答，有一个很好的 ",-1)),i(e,{href:"https://opensource.com/article/21/2/linux-automation"},{default:a(()=>[...s[10]||(s[10]=[t("Anacron",-1)])]),_:1}),s[12]||(s[12]=t("，但它不像 Cron 那样集成的好。要让 Anacron 运行，你需要做很多设置。",-1))]),s[44]||(s[44]=p(`<p>第二个选择是 systemd 计时器。和 Cron 一样，它也是内置的，可以随时使用。你需要写一个单元文件，这肯定比单行的 Crontab 条目多，但也很简单。例如，这里有一个单元文件，在开机 30 分钟后运行一个假想的备份脚本，但每天只运行一次。这可以确保我的电脑得到备份，并防止它每天尝试备份超过一次。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description=Backup</span></span>
<span class="line"><span>Requires=myBackup.service</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Timer]</span></span>
<span class="line"><span>OnBootSec=30min</span></span>
<span class="line"><span>OnUnitActiveSec=1d</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy=timers.target</span></span></code></pre></div><p>当然，你也可以干预并提示运行一个任务。多亏了 <code>OnUnitActiveSec</code> 指令，systemd 不会试图运行你手动激活的作业。</p><h3 id="_3、运行-linux-容器" tabindex="-1">3、运行 Linux 容器 <a class="header-anchor" href="#_3、运行-linux-容器" aria-label="Permalink to “3、运行 Linux 容器”">​</a></h3>`,4)),n("p",null,[s[15]||(s[15]=t("容器使启动一个复杂的服务变得非常容易。你可以在短短几分钟内运行一个 ",-1)),i(e,{href:"https://opensource.com/education/16/3/mattermost-open-source-chat"},{default:a(()=>[...s[13]||(s[13]=[t("Mattermost",-1)])]),_:1}),s[16]||(s[16]=t(" 或 Discourse 服务器。在某些情况下，困难的部分是在你运行容器后管理和监控它们。Podman 使得管理它们变得容易，但是用什么来管理 Podman 呢？嗯，",-1)),i(e,{href:"https://www.redhat.com/sysadmin/podman-run-pods-systemd-services?intcmp=7013a000002qLH8AAM"},{default:a(()=>[...s[14]||(s[14]=[t("你可以使用 systemd",-1)])]),_:1}),s[17]||(s[17]=t("。",-1))]),s[45]||(s[45]=p('<p>Podman 有一个内置的命令来生成单元文件，这样你的容器就可以被 systemd 管理和监控：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ podman generate systemd --new --files --name example_pod</span></span></code></pre></div><p>然后你所要做的就是启动服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl --user start pod-example_pod.service</span></span></code></pre></div><p>和其他服务一样，systemd 确保你的容器荚在任何情况下都能运行。它记录问题，你可以用 <code>journalctl</code> 和其他重要的日志来查看，你也可以用 <code>systemd-cgtop</code> 在控制组中监控它的活动。</p>',5)),n("p",null,[s[19]||(s[19]=t("它不是 ",-1)),i(e,{href:"https://www.redhat.com/en/technologies/cloud-computing/openshift/aws?intcmp=7013a000002qLH8AAM"},{default:a(()=>[...s[18]||(s[18]=[t("Kubernetes 平台",-1)])]),_:1}),s[20]||(s[20]=t("，但对于一两个容器来说，你只需要在可靠和可预测的基础上提供服务，Podman 和 systemd 是一对很棒的组合。",-1))]),s[46]||(s[46]=n("h3",{id:"下载-systemd-电子书",tabindex:"-1"},[t("下载 systemd 电子书 "),n("a",{class:"header-anchor",href:"#下载-systemd-电子书","aria-label":"Permalink to “下载 systemd 电子书”"},"​")],-1)),n("p",null,[s[23]||(s[23]=t("systemd 的内容还有很多，你可以从作者 ",-1)),i(e,{href:"https://opensource.com/users/dboth"},{default:a(()=>[...s[21]||(s[21]=[t("David Both",-1)])]),_:1}),s[24]||(s[24]=t(" 的新书《",-1)),i(e,{href:"https://opensource.com/downloads/pragmatic-guide-systemd-linux"},{default:a(()=>[...s[22]||(s[22]=[t("systemd 实用指南",-1)])]),_:1}),s[25]||(s[25]=t("》中了解基础知识，以及很多实用的技巧。",-1))]),s[47]||(s[47]=n("hr",null,null,-1)),n("p",null,[s[27]||(s[27]=t("via: ",-1)),i(e,{href:"https://opensource.com/article/23/3/3-things-you-didnt-know-systemd-could-do"},{default:a(()=>[...s[26]||(s[26]=[t("https://opensource.com/article/23/3/3-things-you-didnt-know-systemd-could-do",-1)])]),_:1})]),n("p",null,[s[32]||(s[32]=t("作者：",-1)),i(e,{href:"https://opensource.com/users/alansmithee"},{default:a(()=>[...s[28]||(s[28]=[t("Alan Smithee",-1)])]),_:1}),s[33]||(s[33]=t(" 选题：",-1)),i(e,{href:"https://github.com/lkxed/"},{default:a(()=>[...s[29]||(s[29]=[t("lkxed",-1)])]),_:1}),s[34]||(s[34]=t(" 译者：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[30]||(s[30]=[t("wxy",-1)])]),_:1}),s[35]||(s[35]=t(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[31]||(s[31]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[38]||(s[38]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[36]||(s[36]=[t("LCTT",-1)])]),_:1}),s[39]||(s[39]=t(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:a(()=>[...s[37]||(s[37]=[t("Linux中国",-1)])]),_:1}),s[40]||(s[40]=t(" 荣誉推出",-1))])])}const C=l(u,[["render",m]]);export{h as __pageData,C as default};
